mapper.select:
select l.*, coalesce(s.tag_count, 0) as tag_count, coalesce(s.online_count, 0) as online_count, coalesce(s.offline_count, 0) as offline_count, coalesce(s.pending_count, 0) as pending_count from tl_tag_library l left join ( select library_id, count(*) as tag_count, sum(case when status = '2' then 1 else 0 end) as online_count, sum(case when status = '3' then 1 else 0 end) as offline_count, sum(case when status in ('0','1') then 1 else 0 end) as pending_count from tl_tag where del_flag = '0' group by library_id ) s on s.library_id = l.library_id
l.del_flag = '0' and (l.library_name like concat('%', #{libraryName}, '%') or l.library_code like concat('%', #{libraryName}, '%')) and l.category = #{category} and l.tag_object = #{tagObject}
order by l.library_id

