library_name = #{libraryName}, library_code = #{libraryCode}, category = #{category}, tag_object = #{tagObject}, source_table = #{sourceTable}, owner_name = #{ownerName}, status = #{status}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate()
where library_id = #{libraryId}

